FuncDef.Code:
vec3 backdropVerticalGradient(in vec3 dir, in vec3 colorTop, in vec3 colorBottom, in float contrastMul, in float contrastPow)
{
    vec3 color = mix(colorBottom, colorTop, 0.5 * dir.y + 0.5);

    // contrast
    color *= contrastMul;
    color = pow(color, vec3(contrastPow));

    color = clamp(color, 0.0, 1.0);

    return color;
}
